export default {
  name: "DesktopScript",
  data() {
    return {
      // 五个国家中心点的位置（百分比，便于自适应）
      mapDots: [
        { id: 'kz', name: '哈萨克斯坦', left: '13%', top: '18%' },
        { id: 'tm', name: '土库曼斯坦', left: '9%', top: '43%' },
        { id: 'uz', name: '乌兹别克斯坦', left: '12%', top: '36%' },
        { id: 'kg', name: '吉尔吉斯斯坦', left: '18%', top: '31%' },
        { id: 'tj', name: '塔吉克斯坦', left: '25%', top: '52%' }, //19,45
      ],
    };
  },
  methods: {
    onDotClick(dot) {
      // 之后可以在这里加交互逻辑，比如弹出信息框或页面跳转
      console.log('map dot clicked:', dot);
    },
  },
};
